def heading(tool, star):
    slug, _, name, _, description, category = tool
    limits, usage, privacy = HELP[slug]
    return f'''<a href="/tools/" class="back-link">← All tools</a>
<div class="tool-page-heading tool-heading"><div><div class="eyebrow">{escape(category.upper())} / YOUR EVERYDAY TOOLBOX</div><h1>{escape(name)}</h1><p>{escape(description)}</p></div><div class="tool-heading-actions"><button data-favorite="{slug}" class="button secondary favorite" aria-pressed="false">{star} Favorite</button><button class="button secondary" data-open-help aria-haspopup="dialog">Help &amp; limits</button></div></div>
<dialog class="tool-help-dialog" id="tool-help"><button class="button secondary" data-close-help aria-label="Close help">Close ×</button><h2>{escape(name)}</h2><h3>Limits &amp; requirements</h3><p>{escape(limits)}</p><h3>How it works</h3><p>{escape(usage)}</p><h3>Saving &amp; privacy</h3><p>{escape(privacy)}</p></dialog>
<div class="tool-feedback" data-state="ready" role="status" aria-live="polite" aria-atomic="true"><span class="tool-state-label">Ready</span><p class="tool-state-message">{escape(privacy)}</p></div>'''
